package tn.esprit.partnerintelligence.service;import org.springframework.stereotype.Service;import tn.esprit.partnerintelligence.dto.RecommendationDecisionRequest;import tn.esprit.partnerintelligence.entity.RecommendationDecision;import tn.esprit.partnerintelligence.entity.RecommendationItem;import tn.esprit.partnerintelligence.repository.RecommendationDecisionRepository;import tn.esprit.partnerintelligence.repository.RecommendationItemRepository;@Service public class DecisionWorkflowService{ private final RecommendationDecisionRepository dRepo; private final RecommendationItemRepository iRepo; public DecisionWorkflowService(RecommendationDecisionRepository d, RecommendationItemRepository i){dRepo=d;iRepo=i;} public RecommendationDecision decide(Long recommendationId, RecommendationDecisionRequest r){ RecommendationItem item=iRepo.findById(recommendationId).orElseThrow(); item.setStatus(r.decision().toUpperCase()); iRepo.save(item); RecommendationDecision d=new RecommendationDecision(); d.setRecommendationId(recommendationId); d.setDecision(r.decision().toUpperCase()); d.setComment(r.comment()); d.setReviewer(r.reviewer()==null?"system":r.reviewer()); return dRepo.save(d);} }